import { useForm } from 'react-hook-form';import { api } from '../services/api';import { Section } from '../components/Section';import { Seo } from '../components/Seo';import { services } from '../data/content';type FormValues={fullName:string;mobile:string;email:string;dob:string;pan:string;aadhaar:string;address:string;city:string;state:string;occupation:string;company:string;monthlyIncome:number;loanType:string;loanAmount:number;uploadAadhaar:FileList;uploadPAN:FileList;uploadSalarySlip:FileList};export function Apply(){const {register,handleSubmit,formState:{errors,isSubmitting},reset}=useForm<FormValues>();async function submit(data:FormValues){const fd=new FormData();Object.entries(data).forEach(([k,v])=>{if(v instanceof FileList){if(v[0])fd.append(k,v[0])}else fd.append(k,String(v))});await api.post('/loans/apply',fd);alert('Application submitted successfully');reset()}return <><Seo title="Loan Application" description="Secure online loan application."/><Section><h1 className="text-5xl font-black">Loan Application</h1><form onSubmit={handleSubmit(submit)} className="card mt-8 grid gap-4 md:grid-cols-2">{[['fullName','Full Name'],['mobile','Mobile Number'],['email','Email'],['dob','Date of Birth'],['pan','PAN'],['aadhaar','Aadhaar'],['address','Address'],['city','City'],['state','State'],['occupation','Occupation'],['company','Company'],['monthlyIncome','Monthly Income'],['loanAmount','Loan Amount']].map(([name,label])=><label key={name}>{label}<input className="input" type={name==='dob'?'date':name.toLowerCase().includes('amount')||name==='monthlyIncome'?'number':'text'} {...register(name as keyof FormValues,{required:true})}/>{errors[name as keyof FormValues]&&<span className="text-brand-red">Required</span>}</label>)}<label>Loan Type<select className="input" {...register('loanType',{required:true})}>{services.map(s=><option key={s.title}>{s.title}</option>)}</select></label>{['uploadAadhaar','uploadPAN','uploadSalarySlip'].map(n=><label key={n}>{n.replace('upload','Upload ')}<input className="input" type="file" accept="image/*,.pdf" {...register(n as keyof FormValues,{required:true})}/></label>)}<button disabled={isSubmitting} className="btn-primary md:col-span-2">{isSubmitting?'Submitting...':'Submit Application'}</button></form></Section></>}
